//! ✂️ Ranked insertion and removal copy only fixed pages on the changed immutable path.
use super::*;
use crate::retained_clone::{RetainedCloneBinding,RetainedCloneClose,RetainedCloneStep,admit_retained_clone_progress};
use std::mem::ManuallyDrop;
/// 🎮️ Each structural event owns one insertion or one removal at its original rank.
#[derive(Clone,Copy,PartialEq,Eq)]
pub enum PersistentSpliceKind{Insert,Remove}
#[derive(crate::RetireOwned)]#[value(crate="crate")]
enum Scratch<T:RetireOwned+Send+Sync+'static>{Leaf{rows:[Option<SealedShared<T>>;17],count:usize},Branch{children:[Option<SealedShared<Page<T>>>;17],count:usize,height:u8}}
/// 🧳️ Original pages, split candidates and authored row aliases retain typed cancellation custody.
pub struct PersistentSplice<T:RetireOwned+Send+Sync+'static>{
 original:Option<RetainedCloneBinding>,authored:Option<RetainedCloneBinding>,scratch:ManuallyDrop<Option<Scratch<T>>>,candidate:ManuallyDrop<[Option<SealedShared<Page<T>>>;2]>,retirement:RetainedCloneClose,
 kind:PersistentSpliceKind,index:usize,len:usize,height:u8,level:u8,slot:usize,count:usize,rank:usize,changed:usize,pair_count:usize,phase:u8,root_split:bool,closing:bool,
}
impl<T:RetireOwned+Send+Sync+'static> PersistentSplice<T>{
 /// 🌱️ Fixed metadata captures no original row, page or heap allocation.
 pub fn new(kind:PersistentSpliceKind,index:usize)->Self{Self{original:None,authored:None,scratch:ManuallyDrop::new(None),candidate:ManuallyDrop::new(std::array::from_fn(|_|None)),retirement:Default::default(),kind,index,len:0,height:0,level:0,slot:0,count:0,rank:0,changed:0,pair_count:0,phase:0,root_split:false,closing:false}}
 fn page_at<'a>(&self,list:&'a PersistentList<T>)->Result<(Option<&'a Page<T>>,usize),ValueError>{let Some(root)=list.root.as_ref()else{return Ok((None,0));};let mut page=root.get();let mut height=list.height;let mut rank=self.index;while height>self.level{let Page::Branch{children,..}=page else{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"immutable splice lost its original branch"));};let(slot,relative)=child_rank(children,rank,self.kind==PersistentSpliceKind::Insert).ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"immutable splice lost its original rank"))?;rank=relative;page=children[slot].as_ref().ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"immutable splice child is absent"))?.get();height-=1;}Ok((Some(page),rank))}
 /// 📏️ Fixed ranked probes and alias moves copy no retained payload; actual page birth quotes its backing.
 pub fn demand(&self,original:RetainedCloneRef<'_,PersistentList<T>>,authored:Option<RetainedCloneRef<'_,SealedShared<T>>>)->Result<RetirementDemand,ValueError>{if self.closing||self.phase>6{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"immutable splice is closing or transferred"))}if self.original.is_none(){return Ok(RetirementDemand{copy_bytes:original.binding_copy_bytes(),depth:1,..Default::default()})}if self.kind==PersistentSpliceKind::Insert&&self.authored.is_none(){let source=authored.ok_or_else(||ValueError::literal(ValueRefusalKind::InvalidValue,"immutable insertion requires an original authored row source"))?;return Ok(RetirementDemand{copy_bytes:source.binding_copy_bytes(),depth:1,..Default::default()})}let born=match self.phase{3=>self.count>0&&self.candidate[0].is_none(),4=>self.count>0&&self.candidate[1].is_none(),5=>!self.root_split,_=>false};Ok(RetirementDemand{capacity_bytes:if born{SealedShared::<Page<T>>::birth_bytes()}else{0},depth:1,..Default::default()})}
 /// 🧵️ Every actual atomic alias and fallible split birth retains its original source before independent publication.
 pub fn advance(&mut self,original:RetainedCloneRef<'_,PersistentList<T>>,authored:Option<RetainedCloneRef<'_,SealedShared<T>>>,grant:RetainedCloneGrant)->crate::RetainedWorkOutcome{let mut work=0;let result=(||{if self.output_ready(){return Ok(RetainedCloneStep::Complete(Default::default()))}let d=self.demand(original,authored)?;if !fits(d,grant){return Ok(RetainedCloneStep::Progress(Default::default()))}let turn=original.bind(&mut self.original,grant);work=turn.work;if let Some(p)=turn.result?{return Ok(RetainedCloneStep::Progress(p))}if self.kind==PersistentSpliceKind::Insert{let turn=authored.ok_or_else(||ValueError::literal(ValueRefusalKind::InvalidValue,"immutable insertion requires an original authored row source"))?.bind(&mut self.authored,grant);work=turn.work;if let Some(p)=turn.result?{return Ok(RetainedCloneStep::Progress(p))}}work=1;let mut p=RetainedCloneProgress{copied_items:1,..Default::default()};match self.phase{
 0=>{self.height=original.get().height;self.len=original.get().len;let valid=if self.kind==PersistentSpliceKind::Insert{self.index<=self.len}else{self.index<self.len};if !valid{return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"immutable splice rank is outside its original collection").with_retained_progress(p))}self.len=if self.kind==PersistentSpliceKind::Insert{self.len.checked_add(1).ok_or_else(||ValueError::literal(ValueRefusalKind::OwnershipLimit,"immutable insertion cardinality overflow").with_retained_progress(p))?}else{self.len-1};self.phase=1;},
 1=>{let(page,rank)=self.page_at(original.get())?;self.rank=rank;self.slot=0;*self.scratch=Some(match page{None=>{self.count=1;Scratch::Leaf{rows:std::array::from_fn(|_|None),count:1}},Some(Page::Leaf{len,..})=>{self.count=if self.kind==PersistentSpliceKind::Insert{len+1}else{len-1};Scratch::Leaf{rows:std::array::from_fn(|_|None),count:self.count}},Some(Page::Branch{children,height,..})=>{self.changed=child_rank(children,rank,self.kind==PersistentSpliceKind::Insert).ok_or_else(||ValueError::invariant("original splice ancestor rank"))?.0;let count=children.iter().take_while(|c|c.is_some()).count();self.count=count-1+self.pair_count;Scratch::Branch{children:std::array::from_fn(|_|None),count:self.count,height:*height}}});self.phase=if self.count==0{3}else{2};},
 2=>{let(page,_)=self.page_at(original.get())?;match(page,self.scratch.as_mut().ok_or_else(||ValueError::invariant("owned splice scratch"))?){
 (None,Scratch::Leaf{rows,..})=>{let turn=authored.ok_or_else(||ValueError::invariant("authored absent"))?.get().try_duplicate(grant);work=turn.work;let(alias,receipt)=turn.result?;p=receipt;rows[0]=Some(alias);},
 (Some(Page::Leaf{rows:before,..}),Scratch::Leaf{rows,..})=>{let source=if self.kind==PersistentSpliceKind::Insert&&self.slot==self.rank{authored.ok_or_else(||ValueError::invariant("authored absent"))?.get()}else{let from=if self.kind==PersistentSpliceKind::Insert{self.slot-usize::from(self.slot>self.rank)}else{self.slot+usize::from(self.slot>=self.rank)};before[from].as_ref().ok_or_else(||ValueError::invariant("original splice row"))?};let turn=source.try_duplicate(grant);work=turn.work;let(alias,receipt)=turn.result?;p=receipt;rows[self.slot]=Some(alias);},
 (Some(Page::Branch{children:before,..}),Scratch::Branch{children,..})=>{children[self.slot]=if self.slot>=self.changed&&self.slot<self.changed+self.pair_count{self.candidate[self.slot-self.changed].take()}else{let from=if self.slot<self.changed{self.slot}else{self.slot+1-self.pair_count};let turn=before[from].as_ref().ok_or_else(||ValueError::invariant("original splice child"))?.try_duplicate(grant);work=turn.work;let(alias,receipt)=turn.result?;p=receipt;Some(alias)};},_=>return Err(ValueError::invariant("original splice page shape").into())}
 self.slot+=1;if self.slot==self.count{self.phase=3;}},
 3|4=>{let second=self.phase==4;let split=self.count>16;let start=if second{8}else{0};let end=if split&&!second{8}else{self.count};if self.count>0&&self.candidate[usize::from(second)].is_none(){let page=match self.scratch.as_mut().ok_or_else(||ValueError::invariant("owned splice scratch"))?{Scratch::Leaf{rows,..}=>Page::Leaf{rows:std::array::from_fn(|i|if start+i<end{rows[start+i].take()}else{None}),len:end-start},Scratch::Branch{children,height,..}=>{let children=std::array::from_fn(|i|if start+i<end{children[start+i].take()}else{None});let len=children.iter().flatten().map(|c|page_len(c.get())).sum();Page::Branch{children,len,height:*height}}};let turn=SealedShared::admit(page,SharedIssuer::owned(),grant);work=turn.work;return match turn.result{Ok((root,p))=>{self.candidate[usize::from(second)]=Some(root);Ok(RetainedCloneStep::Progress(p))},Err((error,page))=>{match(self.scratch.as_mut().ok_or_else(||ValueError::invariant("scratch absent"))?,page){(Scratch::Leaf{rows,..},Page::Leaf{rows:mut returned,..})=>for i in start..end{rows[i]=returned[i-start].take();},(Scratch::Branch{children,..},Page::Branch{children:mut returned,..})=>for i in start..end{children[i]=returned[i-start].take();},_=>return Err(ValueError::invariant("state invariant violated").into())};Err(error)}}}if split&&!second{self.phase=4;}else{drop(self.scratch.take());self.pair_count=if self.count==0{0}else if split{2}else{1};self.level+=1;self.phase=if self.level>self.height{if self.pair_count==2{5}else{6}}else{1};}},
 5=>{if self.root_split{self.pair_count=1;self.phase=6;}else{let height=self.height.checked_add(1).filter(|height|usize::from(*height)*4<usize::BITS as usize).ok_or_else(||ValueError::literal(ValueRefusalKind::OwnershipLimit,"immutable page height exceeds ranked address space").with_retained_progress(p))?;let children=std::array::from_fn(|i|if i<2{self.candidate[i].take()}else{None});let turn=SealedShared::admit(Page::Branch{children,len:self.len,height},SharedIssuer::owned(),grant);work=turn.work;return match turn.result{Ok((root,p))=>{self.candidate[0]=Some(root);self.root_split=true;Ok(RetainedCloneStep::Progress(p))},Err((error,Page::Branch{mut children,..}))=>{self.candidate[0]=children[0].take();self.candidate[1]=children[1].take();Err(error)},Err((error,_))=>Err(error)}}},
 6=>return Ok(RetainedCloneStep::Complete(Default::default())),_=>return Err(ValueError::invariant("quoted immutable splice phase"))}
 Ok(if self.output_ready(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})})();crate::RetainedWorkOutcome{result,work}}
 /// 👁️ Readiness observes the actual final publication, including a genuinely empty removal result.
 pub fn output_ready(&self)->bool{!self.closing&&self.phase==6}
 /// 📤️ The exact immutable candidate root transfers once after every page birth is admitted.
 pub fn take_demand(&self)->RetirementDemand{RetirementDemand{depth:1,..Default::default()}}
 pub fn take(&mut self,grant:RetainedCloneGrant)->crate::RetainedWorkOutcome<Option<(PersistentList<T>,RetainedCloneProgress)>>{let mut work=0;let result=(||{if self.closing||self.phase!=6{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"immutable splice candidate is not ready"));}let d=self.take_demand();if !fits(d,grant){return Ok(None);}work=1;let root=self.candidate[0].take();self.phase=7;Ok(Some((PersistentList{root,len:self.len,height:if self.len==0{0}else{self.height+u8::from(self.root_split)}},RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})))})();crate::RetainedWorkOutcome{result,work}}
 pub fn begin_close(&mut self){self.closing=true;}
 /// ♻️ Staged split pages and genuine aliases retain their exact original typed issuers.
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.retirement.is_empty(){return self.retirement.next_owner_demands::<Scratch<T>>(false,&None,body);}if self.scratch.is_some(){return self.retirement.next_owner_demands::<Scratch<T>>(true,&None,body);}if self.candidate.iter().any(Option::is_some){return self.retirement.next_owner_demands::<SealedShared<Page<T>>>(true,&None,body);}let b=if self.authored.is_some(){&self.authored}else{&self.original};RetainedCloneBinding::close_demand(b,body)}
 pub fn close_step(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->semio_framework_value_retirement::OriginalRetirementOutcome{let grant=effect.grant();let mut work=0;let result=(|| -> Result<crate::RetainedCloneStep,semio_framework_value_control_contract::OriginalRetirementFailure>{use crate::retained_clone::{RetainedCloneStep,RetainedCloneBinding};if !self.closing{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"immutable splice close not started").into())}if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}let d=self.close_demand(grant.maximum_copy_bytes)?;if !fits(d,grant){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.retirement.is_empty(){let turn=self.retirement.step_granted(grant);work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.progress()))}if self.scratch.is_some(){let turn=self.retirement.begin_granted(&mut self.scratch,grant);work=turn.work;return turn.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default())))}for c in self.candidate.iter_mut(){if c.is_some(){let turn=self.retirement.begin_granted(c,grant);work=turn.work;return turn.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default())))}}let turn=RetainedCloneBinding::close_one(if self.authored.is_some(){&mut self.authored}else{&mut self.original},grant);work=turn.work;let step=turn.result?;Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(step.progress())}else{RetainedCloneStep::Progress(step.progress())})})();crate::RetainedWorkOutcome{result,work}}
 pub fn terminal_is_empty(&self)->bool{self.scratch.is_none()&&self.candidate.iter().all(Option::is_none)&&self.retirement.is_empty()&&self.original.is_none()&&self.authored.is_none()}
}
impl<T:RetireOwned+Send+Sync+'static> Drop for PersistentSplice<T>{fn drop(&mut self){let empty=self.terminal_is_empty();assert!(std::thread::panicking()||empty,"immutable splice requires funded original custody closure");if empty{unsafe{ManuallyDrop::drop(&mut self.scratch);ManuallyDrop::drop(&mut self.candidate);}}}}

